PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS schema_migrations(version INTEGER PRIMARY KEY, applied_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS source_versions(id TEXT PRIMARY KEY, source_id TEXT NOT NULL, url TEXT NOT NULL, title TEXT NOT NULL, retrieved_at TEXT, effective_date_nullable TEXT, sha256 TEXT, excerpt TEXT NOT NULL, review_state TEXT NOT NULL CHECK(review_state IN ('unverified','source_compared','human_reviewed','superseded')), entity_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS review_events(id TEXT PRIMARY KEY, entity_type TEXT NOT NULL, entity_id TEXT NOT NULL, source_version_id TEXT REFERENCES source_versions(id), reviewer_kind TEXT NOT NULL, reviewer_label TEXT NOT NULL, checks_json TEXT NOT NULL, created_at TEXT NOT NULL, entity_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS objectives(id TEXT NOT NULL, version TEXT NOT NULL, source_version_id TEXT REFERENCES source_versions(id), text TEXT NOT NULL, entity_json TEXT NOT NULL, PRIMARY KEY(id,version));
CREATE TABLE IF NOT EXISTS statements(id TEXT NOT NULL, version TEXT NOT NULL, objective_id TEXT NOT NULL, objective_version TEXT NOT NULL, source_version_id TEXT REFERENCES source_versions(id), text TEXT NOT NULL, entity_json TEXT NOT NULL, PRIMARY KEY(id,version), FOREIGN KEY(objective_id,objective_version) REFERENCES objectives(id,version));
CREATE TABLE IF NOT EXISTS skills(id TEXT NOT NULL, version TEXT NOT NULL, title TEXT NOT NULL, status TEXT NOT NULL, entity_json TEXT NOT NULL, PRIMARY KEY(id,version));
CREATE TABLE IF NOT EXISTS alignments(id TEXT PRIMARY KEY, skill_id TEXT NOT NULL, statement_id TEXT NOT NULL, framework_kind TEXT NOT NULL, rationale TEXT NOT NULL, source_version_id TEXT REFERENCES source_versions(id), entity_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS prerequisites(id TEXT PRIMARY KEY, from_skill_id TEXT NOT NULL, to_skill_id TEXT NOT NULL, rationale TEXT NOT NULL, entity_json TEXT NOT NULL, CHECK(from_skill_id <> to_skill_id), UNIQUE(from_skill_id,to_skill_id));
CREATE TABLE IF NOT EXISTS mentor_texts(id TEXT NOT NULL, version TEXT NOT NULL, title TEXT NOT NULL, discipline TEXT NOT NULL, text TEXT NOT NULL, origin_kind TEXT NOT NULL, source_version_id_nullable TEXT REFERENCES source_versions(id), sha256 TEXT NOT NULL, entity_json TEXT NOT NULL, PRIMARY KEY(id,version));
CREATE TABLE IF NOT EXISTS rubrics(id TEXT NOT NULL, version TEXT NOT NULL, source_version_id TEXT REFERENCES source_versions(id), criteria_json TEXT NOT NULL, scale_json TEXT NOT NULL, entity_json TEXT NOT NULL, PRIMARY KEY(id,version));
CREATE TABLE IF NOT EXISTS tasks(id TEXT NOT NULL, version TEXT NOT NULL, kind TEXT NOT NULL, prompt_json TEXT NOT NULL, answer_key_json_nullable TEXT, review_state TEXT NOT NULL CHECK(review_state IN ('draft','source_checked','human_reviewed','retired')), source_refs_json TEXT NOT NULL, mentor_text_id_nullable TEXT, rubric_version_id_nullable TEXT, entity_json TEXT NOT NULL, PRIMARY KEY(id,version));
CREATE TABLE IF NOT EXISTS task_skills(task_id TEXT NOT NULL, task_version TEXT NOT NULL, skill_id TEXT NOT NULL, skill_version TEXT NOT NULL, PRIMARY KEY(task_id,task_version,skill_id), FOREIGN KEY(task_id,task_version) REFERENCES tasks(id,version), FOREIGN KEY(skill_id,skill_version) REFERENCES skills(id,version));
CREATE TABLE IF NOT EXISTS attempts(id TEXT PRIMARY KEY, task_id TEXT NOT NULL, task_version TEXT NOT NULL, session_id TEXT NOT NULL, original_answer_json TEXT NOT NULL, started_at TEXT NOT NULL, submitted_at TEXT NOT NULL, hint_count INTEGER NOT NULL CHECK(hint_count >= 0), assistance_json TEXT NOT NULL, exposure_group_id TEXT NOT NULL, novelty_kind TEXT NOT NULL CHECK(novelty_kind IN ('familiar','unfamiliar')), parent_attempt_id_nullable TEXT REFERENCES attempts(id), entity_json TEXT NOT NULL, FOREIGN KEY(task_id,task_version) REFERENCES tasks(id,version));
CREATE TABLE IF NOT EXISTS judgments(id TEXT PRIMARY KEY, attempt_id TEXT NOT NULL REFERENCES attempts(id), judge_kind TEXT NOT NULL, judge_version TEXT NOT NULL, rubric_version_id_nullable TEXT, result_json TEXT NOT NULL, quoted_evidence_json TEXT NOT NULL, uncertainty_reason_nullable TEXT, supersedes_id_nullable TEXT REFERENCES judgments(id), created_at TEXT NOT NULL, entity_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS evidence_events(id TEXT PRIMARY KEY, attempt_id TEXT NOT NULL REFERENCES attempts(id), judgment_id TEXT NOT NULL REFERENCES judgments(id), skill_id TEXT NOT NULL, evidence_kind TEXT NOT NULL, independence TEXT NOT NULL, eligible INTEGER NOT NULL CHECK(eligible IN (0,1)), exclusion_reason_nullable TEXT, created_at TEXT NOT NULL, entity_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS import_batches(id TEXT PRIMARY KEY, schema_version INTEGER NOT NULL, payload_sha256 TEXT NOT NULL UNIQUE, origin TEXT NOT NULL, imported_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS anki_links(card_stable_id TEXT PRIMARY KEY, note_id_nullable INTEGER, card_ids_json TEXT NOT NULL, deck TEXT NOT NULL, provenance_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS anki_review_events(external_review_id TEXT PRIMARY KEY, card_stable_id TEXT NOT NULL, occurred_at TEXT NOT NULL, rating INTEGER NOT NULL CHECK(rating BETWEEN 1 AND 4), source TEXT NOT NULL, imported_at TEXT NOT NULL, entity_json TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS drafts(task_id TEXT PRIMARY KEY, task_version TEXT NOT NULL, answer_json TEXT NOT NULL, updated_at TEXT NOT NULL, FOREIGN KEY(task_id,task_version) REFERENCES tasks(id,version));
CREATE TABLE IF NOT EXISTS handoff_packets(id TEXT PRIMARY KEY, attempt_id TEXT NOT NULL REFERENCES attempts(id), packet_json TEXT NOT NULL, created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS proposal_approvals(packet_id TEXT PRIMARY KEY REFERENCES handoff_packets(id), proposal_sha256 TEXT NOT NULL, judgment_id TEXT NOT NULL REFERENCES judgments(id));
CREATE INDEX IF NOT EXISTS attempts_task_date ON attempts(task_id,submitted_at);
CREATE INDEX IF NOT EXISTS judgments_attempt_date ON judgments(attempt_id,created_at);
CREATE INDEX IF NOT EXISTS evidence_skill_date ON evidence_events(skill_id,created_at);
CREATE UNIQUE INDEX IF NOT EXISTS evidence_one_skill_judgment ON evidence_events(attempt_id,judgment_id,skill_id);
